import{_ as e,a as d,o as r,a6 as a}from"./chunks/framework.CJDy2q7X.js";const p=JSON.parse('{"title":"Add-Product Search (Create-Order)","description":"","frontmatter":{"outline":false,"examples":[{"id":"admin-products-list","title":"Add-Product Search (Create-Order)","description":"The slim product search behind the admin Create-Order \\"Add Product\\" modal. Not the product listing — for the full datagrid with every column and filter use List Products. Returns all statuses by default, so disabled and draft products appear.","query":"query AdminProducts($first: Int, $after: String, $type: String, $sku: String) {\\n  adminProducts(first: $first, after: $after, type: $type, sku: $sku) {\\n    edges {\\n      cursor\\n      node {\\n        id\\n        _id\\n        sku\\n        type\\n        name\\n        status\\n        price\\n        formattedPrice\\n        baseImageUrl\\n        isSaleable\\n      }\\n    }\\n    pageInfo {\\n      hasNextPage\\n      hasPreviousPage\\n      startCursor\\n      endCursor\\n    }\\n    totalCount\\n  }\\n}\\n","variables":"{\\n  \\"first\\": 30,\\n  \\"type\\": \\"simple\\",\\n  \\"sku\\": \\"SP-001\\"\\n}\\n","response":"{\\n  \\"data\\": {\\n    \\"adminProducts\\": {\\n      \\"edges\\": [\\n        {\\n          \\"cursor\\": \\"MA==\\",\\n          \\"node\\": {\\n            \\"id\\": \\"/api/admin/admin_products/2512\\",\\n            \\"_id\\": 2512,\\n            \\"sku\\": \\"SP-001\\",\\n            \\"type\\": \\"simple\\",\\n            \\"name\\": \\"Arctic Cozy Knit Unisex Beanie\\",\\n            \\"status\\": 1,\\n            \\"price\\": 14,\\n            \\"formattedPrice\\": \\"$14.00\\",\\n            \\"baseImageUrl\\": \\"http://localhost:8000/cache/medium/product/2512/Muc0qeWks34MTZaxf38s6DBmfqMqrCxku81Uo8EB.webp\\",\\n            \\"isSaleable\\": true\\n          }\\n        }\\n      ],\\n      \\"pageInfo\\": {\\n        \\"hasNextPage\\": false,\\n        \\"hasPreviousPage\\": false,\\n        \\"startCursor\\": \\"MA==\\",\\n        \\"endCursor\\": \\"MA==\\"\\n      },\\n      \\"totalCount\\": 1\\n    }\\n  }\\n}\\n"},{"id":"admin-products-search","title":"Free-Text Search","description":"The `query` argument matches SKU or product name partially, which is what the modal\'s search box sends as the admin types.","query":"query AdminProducts($first: Int, $query: String) {\\n  adminProducts(first: $first, query: $query) {\\n    edges {\\n      node {\\n        _id\\n        sku\\n        name\\n        type\\n        isSaleable\\n      }\\n    }\\n    totalCount\\n  }\\n}\\n","variables":"{\\n  \\"first\\": 10,\\n  \\"query\\": \\"beanie\\"\\n}\\n","response":"{\\n  \\"data\\": {\\n    \\"adminProducts\\": {\\n      \\"edges\\": [\\n        {\\n          \\"node\\": {\\n            \\"_id\\": 2512,\\n            \\"sku\\": \\"SP-001\\",\\n            \\"name\\": \\"Arctic Cozy Knit Unisex Beanie\\",\\n            \\"type\\": \\"simple\\",\\n            \\"isSaleable\\": true\\n          }\\n        }\\n      ],\\n      \\"totalCount\\": 1\\n    }\\n  }\\n}\\n"}]},"headers":[],"relativePath":"api/graphql-api/admin/catalog/products/list.md","filePath":"api/graphql-api/admin/catalog/products/list.md","lastUpdated":1787725411000}'),o={name:"api/graphql-api/admin/catalog/products/list.md"};function n(s,t,i,c,l,u){return r(),d("div",null,t[0]||(t[0]=[a('<h1 id="add-product-search-create-order" tabindex="-1">Add-Product Search (Create-Order) <a class="header-anchor" href="#add-product-search-create-order" aria-label="Permalink to &quot;Add-Product Search (Create-Order)&quot;">​</a></h1><p>The slim product <strong>search</strong> behind the admin <strong>Create Order</strong> screen&#39;s &quot;Add Product&quot; modal. It answers one question — which product is the admin picking? — and returns just enough to render a picker row.</p><p>This is not the product listing. For the full admin datagrid, with every column and the Channel / Name / SKU / Attribute Family / Price / ID / Status / Type filters, use <a href="/api/graphql-api/admin/catalog/products.html">List Products</a> (<code>adminCatalogProducts</code>). This page covers only the Create-Order picker.</p><h2 id="operation" tabindex="-1">Operation <a class="header-anchor" href="#operation" aria-label="Permalink to &quot;Operation&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Operation</th><th>Type</th></tr></thead><tbody><tr><td><code>adminProducts</code></td><td>Query (cursor connection)</td></tr></tbody></table><h2 id="arguments" tabindex="-1">Arguments <a class="header-anchor" href="#arguments" aria-label="Permalink to &quot;Arguments&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Arg</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>first</code></td><td>Int</td><td>Page size, default <code>30</code>, capped at <code>50</code>.</td></tr><tr><td><code>after</code></td><td>String</td><td>Cursor from a previous <code>pageInfo.endCursor</code>.</td></tr><tr><td><code>last</code></td><td>Int</td><td>Page size when paging backwards.</td></tr><tr><td><code>before</code></td><td>String</td><td>Cursor from a previous <code>pageInfo.startCursor</code>.</td></tr><tr><td><code>query</code></td><td>String</td><td>Free text — partial match against SKU <strong>or</strong> product name.</td></tr><tr><td><code>sku</code></td><td>String</td><td>Exact SKU.</td></tr><tr><td><code>type</code></td><td>String</td><td><code>simple</code>, <code>configurable</code>, <code>bundle</code>, <code>downloadable</code>, <code>grouped</code>, <code>virtual</code>, or <code>booking</code>.</td></tr><tr><td><code>status</code></td><td>Int</td><td><code>0</code> disabled, <code>1</code> enabled. Omit to get both.</td></tr><tr><td><code>categoryId</code></td><td>Int</td><td>Restrict to products in one category.</td></tr><tr><td><code>channel</code></td><td>String</td><td>Channel code used to resolve <code>name</code> and <code>price</code>.</td></tr><tr><td><code>locale</code></td><td>String</td><td>Locale code used to resolve <code>name</code>.</td></tr></tbody></table><p>Arguments combine with AND — more arguments narrow the result. <code>query</code> and <code>sku</code> are separate: <code>query</code> is the partial &quot;as you type&quot; match, <code>sku</code> is exact.</p><h2 id="node-fields" tabindex="-1">Node Fields <a class="header-anchor" href="#node-fields" aria-label="Permalink to &quot;Node Fields&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>ID!</td><td>Resource identifier in IRI form, <code>/api/admin/admin_products/&lt;id&gt;</code>.</td></tr><tr><td><code>_id</code></td><td>Int</td><td>Numeric product id — the value to send when adding the item to a cart.</td></tr><tr><td><code>sku</code></td><td>String</td><td>Product SKU.</td></tr><tr><td><code>type</code></td><td>String</td><td>Product type.</td></tr><tr><td><code>name</code></td><td>String</td><td>Resolved for the requested channel and locale.</td></tr><tr><td><code>status</code></td><td>Int</td><td><code>1</code> enabled, <code>0</code> disabled.</td></tr><tr><td><code>price</code></td><td>Float</td><td>Minimal price for the product.</td></tr><tr><td><code>formattedPrice</code></td><td>String</td><td>The same price rendered in the channel currency.</td></tr><tr><td><code>baseImageUrl</code></td><td>String</td><td>Medium-size image URL, falling back to the theme placeholder when the product has no image.</td></tr><tr><td><code>isSaleable</code></td><td>Boolean</td><td>Whether the product can currently be sold.</td></tr></tbody></table><p>The row is deliberately nine fields — no variants, bundle options, images array, or attribute values. Use <a href="/api/graphql-api/admin/catalog/products/products-detail.html">Product Detail</a> once a product is picked.</p><p>Two fields behave unlike their storefront counterparts:</p><ul><li><strong><code>status</code> and <code>price</code> are typed numbers here</strong>, not strings. Elsewhere in the admin catalog schema the same concepts arrive as strings — do not share a parsing helper between this query and <code>adminCatalogProducts</code>.</li><li><strong><code>baseImageUrl</code> is never null.</strong> A product without an image gets the theme&#39;s placeholder URL, so an &quot;is there an image?&quot; check on this field always says yes.</li></ul><h2 id="how-it-differs-from-the-storefront-query" tabindex="-1">How It Differs From the Storefront Query <a class="header-anchor" href="#how-it-differs-from-the-storefront-query" aria-label="Permalink to &quot;How It Differs From the Storefront Query&quot;">​</a></h2><ul><li><strong>No implicit <code>status = 1</code> filter.</strong> The storefront <code>products</code> query hides disabled products; this one returns every status so an admin can find a draft or disabled product. Pass <code>status: 1</code> explicitly if you want only enabled ones.</li><li><strong>Booking products are returned.</strong> They are listed so the admin can find them, but adding one to a draft cart fails — see <a href="/api/graphql-api/admin/sales/carts/add-item.html">Add Item to Cart</a>. This mirrors the admin panel, whose Create-Order screen ships no booking form.</li><li><strong>Nine fields, not the full product schema.</strong></li></ul><h2 id="errors" tabindex="-1">Errors <a class="header-anchor" href="#errors" aria-label="Permalink to &quot;Errors&quot;">​</a></h2><p>Requires an admin Bearer token. There is no separate permission gate on the search itself.</p>',17)]))}const m=e(o,[["render",n]]);export{p as __pageData,m as default};
